window.kbPageData["views/entry/k-47400b475fbe4398"] = {"key":"entry/k-47400b475fbe4398","state":{"route":"entry/k-47400b475fbe4398"},"node":{"id":"k-47400b475fbe4398","mode":"k","title":"社会主义的产生和发展 · 空想社会主义的进步性和局限性","type":"原理与机制","domain":"政治理论","reading":"","intro":"","priority":100,"aliases":[],"qs":[],"current":false,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":true,"tags":{"主类":["原理与机制"],"出处性质":["理论手册"],"学科":["政治理论"],"来源主题":["科学社会主义"],"资料类别":["非时政"]},"directorySummary":"一、空想社会主义的进步性和局限性\n19 世纪初期以圣西门、傅立叶、欧文为代表的空想社会主义是科学社会主义的直接思\n想来源。\n1.空想社会主义的进步性：\n（1）在理论上致力于社会制度的分析；\n（2）对资本主义旧制度的批判包含着许多击中要害的见解；\n（3）对社会主义新制度的描绘，闪烁着诸多天才的火花。\n…","sources":[{"id":"029304ab608f49e2","label":"社会主义的产生和发展 · 空想社会主义的进步性和局限性","topic":"科学社会主义","category":"非时政","text":"一、空想社会主义的进步性和局限性\n19 世纪初期以圣西门、傅立叶、欧文为代表的空想社会主义是科学社会主义的直接思\n想来源。\n1.空想社会主义的进步性：\n（1）在理论上致力于社会制度的分析；\n（2）对资本主义旧制度的批判包含着许多击中要害的见解；\n（3）对社会主义新制度的描绘，闪烁着诸多天才的火花。\n2.空想社会主义的局限性：\n（1）看到了资本主义必然灭亡的命运，却未能揭示资本主义必然灭亡的经济根源；\n（2）要求埋葬资本主义，却看不到埋葬资本主义的力量；\n（3）憧憬取代资本主义的理想社会，却找不到通往理想社会的现实道路。","source":{"doc":"3ccc56f4000d1642c2d1","first":11,"last":11,"page":11,"file":"政治理论必学手册.pdf"},"basis":"理论手册"}]},"questions":{},"terms":{},"references":{},"topics":[],"units":{"k-47400b475fbe4398":[]}};
